pirate_flagship.source:
export const envelope = [19, 36, 47];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 9; // Ship centerline in X

  // Palette from theme with pirate timber fallbacks
  const woodPlanks = api.theme.wood.planks || "minecraft:dark_oak_planks";
  const woodLog = api.theme.wood.log || "minecraft:dark_oak_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_dark_oak_log";
  const woodStairs = api.theme.wood.stairs || "minecraft:dark_oak_stairs";
  const woodSlab = api.theme.wood.slab || "minecraft:dark_oak_slab";
  const woodFence = api.theme.wood.fence || "minecraft:dark_oak_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:dark_oak_trapdoor";

  // 3D Voxel buffer for clean deterministic construction
  const grid = new Array(W);
  for (let x = 0; x < W; x++) {
    grid[x] = new Array(H);
    for (let y = 0; y < H; y++) {
      grid[x][y] = new Array(D).fill(null);
    }
  }

  function setV(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      grid[x][y][z] = block;
    }
  }

  function getV(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x][y][z];
    }
    return null;
  }

  // Hull profile parametric functions
  function yBottom(z) {
    if (z < 6) return 5;
    if (z === 6) return 4;
    if (z <= 9) return Math.round(4 - (z - 6) * 1.0);
    if (z <= 36) return 1;
    if (z <= 43) return Math.round(1 + (z - 36) * 0.5);
    return 5;
  }

  function yTop(z) {
    if (z < 6) return 10;
    if (z <= 13) return 11; // Forecastle
    if (z <= 29) return 10; // Waist
    if (z <= 37) return 13; // Quarterdeck
    if (z <= 43) return 16; // Poop deck / Stern
    return 10;
  }

  function hwMax(z) {
    if (z < 6 || z > 43) return 0;
    if (z === 6) return 0.8;
    if (z === 7) return 1.8;
    if (z === 8) return 2.8;
    if (z === 9) return 3.6;
    if (z <= 13) return 4.4;
    if (z <= 29) return 4.8;
    if (z <= 37) return 4.6;
    if (z <= 41) return 4.2;
    return 3.8;
  }

  function halfWidth(z, y) {
    const yB = yBottom(z);
    const yT = yTop(z);
    if (y < yB || y > yT) return -1;
    const maxW = hwMax(z);
    if (maxW <= 0) return -1;
    const t = (y - yB) / Math.max(1, (yT - yB));
    let wf = 0.3;
    if (t <= 0.5) {
      wf = 0.3 + 0.7 * (t / 0.5);
    } else {
      wf = 1.0 - 0.12 * ((t - 0.5) / 0.5); // tumblehome
    }
    return maxW * wf;
  }

  // 1. Hull Shell and Framing
  for (let z = 6; z <= 43; z++) {
    const yB = yBottom(z);
    const yT = yTop(z);
    const isFrame = (z % 3 === 1) || z === 6 || z === 43;

    for (let y = yB; y <= yT; y++) {
      const hw = halfWidth(z, y);
      if (hw < 0) continue;
      const minX = Math.round(cx - hw);
      const maxX = Math.round(cx + hw);

      for (let x = minX; x <= maxX; x++) {
        const isWall = (x === minX || x === maxX || y === yB || y === yB + 1);
        if (isWall) {
          if (y === 5) {
            // Rubbing strake / waterline accent
            setV(x, y, z, "minecraft:stripped_dark_oak_log[axis=z]");
          } else if (isFrame && (x === minX || x === maxX)) {
            setV(x, y, z, "minecraft:dark_oak_log[axis=y]");
          } else if (y === yT && (x === minX || x === maxX)) {
            // Bulwark cap
            setV(x, y, z, woodPlanks);
          } else {
            setV(x, y, z, woodPlanks);
          }
        }
      }
    }
  }

  // 2. Solid Keel and seabed support
  for (let z = 6; z <= 43; z++) {
    const yB = yBottom(z);
    for (let y = 0; y <= yB; y++) {
      setV(cx, y, z, "minecraft:dark_oak_log[axis=z]");
    }
    // Ground reach down
    const groundH = Math.max(0, Math.floor(api.heightAt(cx, z)));
    for (let y = groundH; y < 0; y++) {
      // Keel stays grounded
      setV(cx, y, z, "minecraft:dark_oak_log[axis=z]");
    }
  }

  // 3. Decks (Flooring)
  function buildDeck(yLvl, minZ, maxZ) {
    for (let z = minZ; z <= maxZ; z++) {
      const hw = halfWidth(z, yLvl);
      if (hw < 0) continue;
      const minX = Math.round(cx - hw) + 1;
      const maxX = Math.round(cx + hw) - 1;
      for (let x = minX; x <= maxX; x++) {
        setV(x, yLvl, z, woodPlanks);
      }
    }
  }

  // Gun deck floor
  buildDeck(5, 8, 41);
  // Waist deck floor
  buildDeck(9, 14, 29);
  // Forecastle deck floor
  buildDeck(10, 7, 13);
  // Quarterdeck floor
  buildDeck(12, 30, 37);
  // Poop deck floor
  buildDeck(15, 38, 43);

  // 4. Bulkheads and Interior Partitions
  // Forecastle forward bulkhead (z=13)
  for (let x = cx - 3; x <= cx + 3; x++) {
    for (let y = 6; y <= 9; y++) {
      setV(x, y, 13, woodPlanks);
    }
  }
  // Doorway into forecastle gun room
  setV(cx, 6, 13, null);
  setV(cx, 7, 13, null);

  // Quarterdeck bulkhead (z=30)
  for (let x = cx - 3; x <= cx + 3; x++) {
    for (let y = 10; y <= 12; y++) {
      setV(x, y, 30, woodPlanks);
    }
  }
  // Doors to captain's cabin
  setV(cx - 1, 10, 30, null);
  setV(cx - 1, 11, 30, null);
  setV(cx + 1, 10, 30, null);
  setV(cx + 1, 11, 30, null);
  setV(cx - 1, 10, 30, "minecraft:dark_oak_door[facing=south,half=lower]");
  setV(cx - 1, 11, 30, "minecraft:dark_oak_door[facing=south,half=upper]");
  setV(cx + 1, 10, 30, "minecraft:dark_oak_door[facing=south,half=lower]");
  setV(cx + 1, 11, 30, "minecraft:dark_oak_door[facing=south,half=upper]");

  // Stairs between decks
  // Waist to Forecastle
  setV(cx - 2, 9, 13, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
  setV(cx + 2, 9, 13, "minecraft:dark_oak_stairs[facing=south,half=bottom]");
  setV(cx - 2, 10, 13, null);
  setV(cx + 2, 10, 13, null);

  // Waist to Quarterdeck
  setV(cx - 2, 9, 29, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setV(cx + 2, 9, 29, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setV(cx - 2, 10, 29, "minecraft:dark_oak_stairs[facing=north,half=top]");
  setV(cx + 2, 10, 29, "minecraft:dark_oak_stairs[facing=north,half=top]");
  setV(cx - 2, 11, 30, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setV(cx + 2, 11, 30, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setV(cx - 2, 12, 30, null);
  setV(cx + 2, 12, 30, null);

  // Quarterdeck to Poop Deck
  setV(cx - 2, 12, 37, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setV(cx + 2, 12, 37, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setV(cx - 2, 13, 37, "minecraft:dark_oak_stairs[facing=north,half=top]");
  setV(cx + 2, 13, 37, "minecraft:dark_oak_stairs[facing=north,half=top]");
  setV(cx - 2, 14, 38, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setV(cx + 2, 14, 38, "minecraft:dark_oak_stairs[facing=north,half=bottom]");
  setV(cx - 2, 15, 38, null);
  setV(cx + 2, 15, 38, null);

  // 5. Clear Specified Interiors (strictly empty for compiler fit-out)
  // Gun deck hall
  for (let x = 6; x <= 12; x++) {
    for (let y = 6; y <= 8; y++) {
      for (let z = 15; z <= 28; z++) {
        setV(x, y, z, null);
      }
    }
  }

  // Captain's Quarters
  for (let x = 7; x <= 11; x++) {
    for (let y = 12; y <= 14; y++) {
      for (let z = 32; z <= 38; z++) {
        setV(x, y, z, null);
      }
    }
  }

  // 6. Broadside Cannons & Gunports
  const gunZ = [16, 19, 23, 27];
  for (const gz of gunZ) {
    const hwG = halfWidth(gz, 6);
    const leftX = Math.round(cx - hwG);
    const rightX = Math.round(cx + hwG);

    // Port side gunport & cannon
    setV(leftX, 6, gz, "minecraft:dispenser[facing=west]");
    setV(leftX + 1, 6, gz, "minecraft:polished_blackstone");
    setV(leftX, 7, gz, "minecraft:dark_oak_trapdoor[facing=west,half=top,open=true]");

    // Starboard side gunport & cannon
    setV(rightX, 6, gz, "minecraft:dispenser[facing=east]");
    setV(rightX - 1, 6, gz, "minecraft:polished_blackstone");
    setV(rightX, 7, gz, "minecraft:dark_oak_trapdoor[facing=east,half=top,open=true]");
  }

  // Upper deck swivel guns (Waist bulwark)
  const swivelZ = [15, 21, 28];
  for (const sz of swivelZ) {
    const hwW = halfWidth(sz, 10);
    const lx = Math.round(cx - hwW);
    const rx = Math.round(cx + hwW);
    setV(lx, 11, sz, woodFence);
    setV(lx, 12, sz, "minecraft:polished_blackstone");
    setV(rx, 11, sz, woodFence);
    setV(rx, 12, sz, "minecraft:polished_blackstone");
  }

  // 7. Stern Transom, Windows & Balcony
  // Transom wall at z=43
  for (let x = cx - 3; x <= cx + 3; x++) {
    for (let y = 5; y <= 16; y++) {
      setV(x, y, 43, woodPlanks);
    }
  }
  // Ornate bay windows on captain's cabin
  setV(cx - 2, 13, 43, "minecraft:red_stained_glass_pane");
  setV(cx, 13, 43, "minecraft:red_stained_glass_pane");
  setV(cx + 2, 13, 43, "minecraft:red_stained_glass_pane");
  setV(cx - 2, 14, 43, "minecraft:dark_oak_stairs[facing=north,half=top]");
  setV(cx, 14, 43, "minecraft:dark_oak_stairs[facing=north,half=top]");
  setV(cx + 2, 14, 43, "minecraft:dark_oak_stairs[facing=north,half=top]");

  // Stern Balcony (z=44)
  for (let x = cx - 3; x <= cx + 3; x++) {
    setV(x, 11, 44, woodPlanks);
    setV(x, 12, 44, woodFence);
  }
  // Stern decorative gold trim & skull crest
  setV(cx, 16, 43, "minecraft:gilded_blackstone");
  setV(cx - 1, 16, 43, "minecraft:gold_block");
  setV(cx + 1, 16, 43, "minecraft:gold_block");
  setV(cx, 15, 43, "minecraft:bone_block[axis=y]");

  // Stern lanterns
  setV(cx - 3, 13, 44, "minecraft:dark_oak_fence");
  setV(cx - 3, 12, 44, "minecraft:soul_lantern[hanging=true]");
  setV(cx + 3, 13, 44, "minecraft:dark_oak_fence");
  setV(cx + 3, 12, 44, "minecraft:soul_lantern[hanging=true]");
  setV(cx, 17, 44, "minecraft:dark_oak_fence");
  setV(cx, 16, 44, "minecraft:lantern[hanging=true]");

  // Rudder
  for (let y = 2; y <= 8; y++) {
    setV(cx, y, 44, "minecraft:dark_oak_planks");
  }

  // 8. Bowsprit and Jib Boom
  // Spar projecting forward through stem
  const bowCoords = [
    [cx, 11, 9], [cx, 12, 8], [cx, 12, 7], [cx, 13, 6],
    [cx, 13, 5], [cx, 14, 4], [cx, 14, 3], [cx, 15, 2], [cx, 15, 1]
  ];
  for (const [bx, by, bz] of bowCoords) {
    setV(bx, by, bz, "minecraft:stripped_dark_oak_log[axis=z]");
  }
  // Bowsprit cap & stays
  setV(cx, 16, 1, woodFence);
  setV(cx, 16, 2, "minecraft:chain[axis=z]");
  setV(cx, 15, 3, "minecraft:chain[axis=z]");

  // 9. Giant Skull Figurehead (Facing North -Z)
  // Cranium (y=12..13, z=4..6, x=cx-1..cx+1)
  for (let x = cx - 1; x <= cx + 1; x++) {
    for (let y = 12; y <= 13; y++) {
      for (let z = 5; z <= 6; z++) {
        setV(x, y, z, "minecraft:bone_block[axis=y]");
      }
    }
  }
  setV(cx, 13, 4, "minecraft:bone_block[axis=z]"); // Cranium brow

  // Eyes and glowing soul sockets (y=11)
  setV(cx - 1, 11, 5, "minecraft:crying_obsidian"); // Port eye
  setV(cx + 1, 11, 5, "minecraft:crying_obsidian"); // Starboard eye
  setV(cx, 11, 5, "minecraft:bone_block[axis=y]"); // Nasal bridge
  setV(cx - 1, 11, 6, "minecraft:soul_lantern[hanging=false]"); // Eye glow behind
  setV(cx + 1, 11, 6, "minecraft:soul_lantern[hanging=false]");

  // Upper Jaw & Fangs (y=10)
  setV(cx, 10, 5, "minecraft:black_concrete"); // Nasal cavity
  setV(cx - 1, 10, 5, "minecraft:smooth_quartz_stairs[facing=south,half=top]");
  setV(cx + 1, 10, 5, "minecraft:smooth_quartz_stairs[facing=south,half=top]");
  setV(cx, 10, 4, "minecraft:smooth_quartz_stairs[facing=south,half=top]");

  // Lower Jaw (y=9)
  setV(cx - 1, 9, 5, "minecraft:bone_block[axis=y]");
  setV(cx + 1, 9, 5, "minecraft:bone_block[axis=y]");
  setV(cx, 9, 4, "minecraft:smooth_quartz_stairs[facing=north,half=bottom]");
  setV(cx, 9, 5, "minecraft:bone_block[axis=z]");

  // Skull Bandana & Pirate Accents
  setV(cx - 1, 14, 5, "minecraft:red_wool");
  setV(cx, 14, 5, "minecraft:red_wool");
  setV(cx + 1, 14, 5, "minecraft:red_wool");
  setV(cx, 14, 6, "minecraft:red_wool");
  setV(cx - 2, 11, 5, "minecraft:gold_block"); // Gold earring on pirate skull!

  // Cutwater support ram under figurehead
  for (let y = 6; y <= 8; y++) {
    setV(cx, y, 6, "minecraft:stripped_dark_oak_log[axis=y]");
  }

  // 10. Three Masts and Rigging
  const masts = [
    { name: "fore", z: 12, minY: 10, maxY: 29, topY: 20 },
    { name: "main", z: 22, minY: 8, maxY: 34, topY: 22 },
    { name: "mizzen", z: 33, minY: 14, maxY: 28, topY: 21 }
  ];

  for (const m of masts) {
    // Mast column
    for (let y = m.minY; y <= m.maxY; y++) {
      setV(cx, y, m.z, "minecraft:dark_oak_log[axis=y]");
    }

    // Crow's Nest / Fighting Top
    const ty = m.topY;
    for (let x = cx - 1; x <= cx + 1; x++) {
      for (let z = m.z - 1; z <= m.z + 1; z++) {
        if (x !== cx || z !== m.z) {
          setV(x, ty, z, "minecraft:dark_oak_slab[type=bottom]");
          setV(x, ty + 1, z, woodFence);
        }
      }
    }

    // Shrouds (Ratlines climbing up to top)
    const hwS = Math.max(3, Math.round(halfWidth(m.z, m.minY)));
    for (let y = m.minY + 1; y <= ty; y++) {
      setV(cx - hwS, y, m.z, woodFence);
      setV(cx + hwS, y, m.z, woodFence);
    }
  }

  // Helper function to build Billowing Sails
  function buildSail(mastZ, yardY, sailH, yardSpan, isMainCourse) {
    // Yardarm
    const halfSpan = Math.floor(yardSpan / 2);
    for (let x = cx - halfSpan; x <= cx + halfSpan; x++) {
      setV(x, yardY, mastZ, "minecraft:stripped_dark_oak_log[axis=x]");
    }
    // Yardarm tapered tips
    setV(cx - halfSpan - 1, yardY, mastZ, woodFence);
    setV(cx + halfSpan + 1, yardY, mastZ, woodFence);

    // Billowing canvas
    const sailSpan = yardSpan - 2;
    const halfSail = Math.floor(sailSpan / 2);

    for (let dy = 1; dy <= sailH; dy++) {
      const y = yardY - dy;
      // Belly curve towards North (-Z)
      const normY = dy / sailH;
      const billow = Math.round(1.6 * Math.sin(normY * Math.PI));
      const sailZ = mastZ - billow;

      for (let x = cx - halfSail; x <= cx + halfSail; x++) {
        let block = "minecraft:black_wool";

        if (isMainCourse) {
          // JOLLY ROGER EMBLEM in White Wool
          const dx = Math.abs(x - cx);
          if (dy === 2 && dx <= 1) block = "minecraft:white_wool"; // Skull top
          if (dy === 3 && dx <= 1) {
            block = (dx === 1) ? "minecraft:black_wool" : "minecraft:white_wool"; // Eyes
          }
          if (dy === 4 && dx === 0) block = "minecraft:white_wool"; // Teeth
          // Crossed Cutlasses
          if (dy === 5 && (dx === 1 || dx === 2)) block = "minecraft:white_wool";
          if (dy === 3 && (dx === 3 || dx === 4)) block = "minecraft:white_wool";
          if (dy === 1 && (dx === 4 || dx === 5)) block = "minecraft:white_wool";
        } else {
          // Dark canvas texture variation
          if ((x + y) % 5 === 0) block = "minecraft:gray_wool";
        }

        setV(x, y, sailZ, block);
      }
    }
  }

  // Foremast Sails (z=12)
  buildSail(12, 17, 4, 11, false); // Fore-course
  buildSail(12, 25, 3, 7, false);  // Fore-topsail
  // Fore pennant
  for (let z = 13; z <= 15; z++) {
    setV(cx, 29, z, "minecraft:black_wool");
  }

  // Mainmast Sails (z=22) - FLAGSHIP CENTERPIECE
  buildSail(22, 17, 6, 13, true);  // Grand Main Course with Jolly Roger
  buildSail(22, 26, 3, 9, false); // Main topsail
  buildSail(22, 31, 2, 5, false); // Main topgallant
  // Main Jolly Roger Masthead Flag
  for (let z = 23; z <= 26; z++) {
    setV(cx, 34, z, "minecraft:black_wool");
    setV(cx, 35, z, "minecraft:black_wool");
  }
  setV(cx, 34, 24, "minecraft:white_wool"); // Mini skull on flag

  // Mizzenmast Sails (z=33)
  buildSail(33, 19, 3, 9, false); // Mizzen course
  buildSail(33, 25, 2, 5, false); // Mizzen topsail
  // Mizzen pennant
  for (let z = 34; z <= 36; z++) {
    setV(cx, 28, z, "minecraft:red_wool");
  }

  // Jib Stay and Headsail (Bow)
  for (let step = 0; step <= 6; step++) {
    const jz = 2 + step;
    const jy = 15 + Math.round(step * 0.7);
    setV(cx, jy, jz, "minecraft:chain[axis=z]");
    if (step >= 2 && step <= 5) {
      setV(cx, jy - 1, jz, "minecraft:black_wool");
      setV(cx, jy - 2, jz, "minecraft:gray_wool");
    }
  }

  // Horizontal Stays between Masts
  for (let z = 13; z <= 21; z++) {
    setV(cx, 20, z, "minecraft:chain[axis=z]");
  }
  for (let z = 23; z <= 32; z++) {
    setV(cx, 21, z, "minecraft:chain[axis=z]");
  }

  // 11. Deck Fittings and Nautical Details
  // Ship's Helm / Wheel on Quarterdeck
  setV(cx, 13, 31, woodFence);
  setV(cx, 14, 31, "minecraft:dark_oak_trapdoor[facing=north,half=top,open=true]");

  // Ship's Bell at Foremast
  setV(cx, 11, 13, "minecraft:bell[facing=south]");

  // Anchor Capstan on Forecastle
  setV(cx, 11, 9, "minecraft:stripped_dark_oak_log[axis=y]");
  setV(cx, 12, 9, "minecraft:dark_oak_trapdoor[facing=north,half=bottom,open=false]");

  // Cargo Hatch Grating on Main Deck
  setV(cx, 9, 17, "minecraft:dark_oak_trapdoor[facing=north,half=bottom,open=false]");
  setV(cx, 9, 18, "minecraft:dark_oak_trapdoor[facing=north,half=bottom,open=false]");

  // Deck Lanterns
  setV(cx - 3, 11, 15, woodFence);
  setV(cx - 3, 12, 15, "minecraft:lantern[hanging=false]");
  setV(cx + 3, 11, 15, woodFence);
  setV(cx + 3, 12, 15, "minecraft:lantern[hanging=false]");

  setV(cx - 3, 11, 28, woodFence);
  setV(cx - 3, 12, 28, "minecraft:soul_lantern[hanging=false]");
  setV(cx + 3, 11, 28, woodFence);
  setV(cx + 3, 12, 28, "minecraft:soul_lantern[hanging=false]");

  // Bulwark Railing Fences
  for (let z = 7; z <= 12; z++) {
    const hw = halfWidth(z, 11);
    setV(Math.round(cx - hw), 12, z, woodFence);
    setV(Math.round(cx + hw), 12, z, woodFence);
  }
  for (let z = 38; z <= 42; z++) {
    const hw = halfWidth(z, 16);
    setV(Math.round(cx - hw), 17, z, woodFence);
    setV(Math.round(cx + hw), 17, z, woodFence);
  }

  // 12. Emit All Blocks to Engine
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const block = grid[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "pirate_flagship",
    seatY: 0,
    anchors: {
      front: [cx, 11, 0],       // Facing North towards unicorn island
      board: [cx - 4, 9, 21],    // Midship boarding ladder
      helm: [cx, 13, 31]         // Quarterdeck helm
    },
    interiors: [
      {
        min: [6, 6, 15],
        max: [12, 8, 28],
        kind: "hall"
      },
      {
        min: [7, 12, 32],
        max: [11, 14, 38],
        kind: "quarters"
      }
    ]
  };
}

celestial_unicorn_monument.source:
export const envelope = [23, 42, 23];

export default function build(api) {
  const [W, H, D] = api.size;
  const cx = 11;
  const cz = 12;
  const seatY = 4;

  // 3D voxel grid
  const voxels = Array.from({ length: W }, () =>
    Array.from({ length: H }, () => new Array(D).fill(null))
  );

  function set(x, y, z, block) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      voxels[ix][iy][iz] = block;
    }
  }

  function get(x, y, z) {
    const ix = Math.floor(x);
    const iy = Math.floor(y);
    const iz = Math.floor(z);
    if (ix >= 0 && ix < W && iy >= 0 && iy < H && iz >= 0 && iz < D) {
      return voxels[ix][iy][iz];
    }
    return null;
  }

  function fillTaperedCapsule(x0, y0, z0, r0, x1, y1, z1, r1, block) {
    const maxR = Math.max(r0, r1) + 1;
    const minX = Math.max(0, Math.floor(Math.min(x0, x1) - maxR));
    const maxX = Math.min(W - 1, Math.ceil(Math.max(x0, x1) + maxR));
    const minY = Math.max(0, Math.floor(Math.min(y0, y1) - maxR));
    const maxY = Math.min(H - 1, Math.ceil(Math.max(y0, y1) + maxR));
    const minZ = Math.max(0, Math.floor(Math.min(z0, z1) - maxR));
    const maxZ = Math.min(D - 1, Math.ceil(Math.max(z0, z1) + maxR));

    const vx = x1 - x0, vy = y1 - y0, vz = z1 - z0;
    const vLenSq = vx * vx + vy * vy + vz * vz;

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          let t = 0;
          if (vLenSq > 0.0001) {
            const wx = x - x0, wy = y - y0, wz = z - z0;
            t = (wx * vx + wy * vy + wz * vz) / vLenSq;
            t = Math.max(0, Math.min(1, t));
          }
          const px = x0 + t * vx;
          const py = y0 + t * vy;
          const pz = z0 + t * vz;
          const dx = x - px, dy = y - py, dz = z - pz;
          const distSq = dx * dx + dy * dy + dz * dz;
          const r = r0 + t * (r1 - r0);
          if (distSq <= r * r) {
            set(x, y, z, block);
          }
        }
      }
    }
  }

  function fillCapsule(x0, y0, z0, x1, y1, z1, r, block) {
    fillTaperedCapsule(x0, y0, z0, r, x1, y1, z1, r, block);
  }

  function fillEllipsoid(ecx, ecy, ecz, rx, ry, rz, block) {
    const minX = Math.max(0, Math.floor(ecx - rx));
    const maxX = Math.min(W - 1, Math.ceil(ecx + rx));
    const minY = Math.max(0, Math.floor(ecy - ry));
    const maxY = Math.min(H - 1, Math.ceil(ecy + ry));
    const minZ = Math.max(0, Math.floor(ecz - rz));
    const maxZ = Math.min(D - 1, Math.ceil(ecz + rz));

    for (let x = minX; x <= maxX; x++) {
      const dx = (x - ecx) / rx;
      for (let y = minY; y <= maxY; y++) {
        const dy = (y - ecy) / ry;
        for (let z = minZ; z <= maxZ; z++) {
          const dz = (z - ecz) / rz;
          if (dx * dx + dy * dy + dz * dz <= 1.0) {
            set(x, y, z, block);
          }
        }
      }
    }
  }

  function setCluster(x, y, z, facing) {
    let sx = x, sy = y, sz = z;
    if (facing === "up") sy = y - 1;
    else if (facing === "down") sy = y + 1;
    else if (facing === "north") sz = z + 1;
    else if (facing === "south") sz = z - 1;
    else if (facing === "east") sx = x - 1;
    else if (facing === "west") sx = x + 1;

    if (get(sx, sy, sz) !== null && get(x, y, z) === null) {
      set(x, y, z, `minecraft:amethyst_cluster[facing=${facing}]`);
    }
  }

  // --- PALETTE ---
  const plinth = api.theme?.ground?.plinth || "minecraft:quartz_bricks";
  const quartzBrick = "minecraft:quartz_bricks";
  const smoothQuartz = "minecraft:smooth_quartz";
  const quartzPillar = "minecraft:quartz_pillar[axis=y]";
  const gold = "minecraft:gold_block";
  const seaLantern = "minecraft:sea_lantern";
  const amethyst = "minecraft:amethyst_block";
  const cryingObsidian = "minecraft:crying_obsidian";
  const tintedGlass = "minecraft:tinted_glass";

  // --- 1. FOUNDATION & STEPPED PEDESTAL ---
  // Ground following down to terrain height
  for (let x = 2; x <= 20; x++) {
    for (let z = 3; z <= 21; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      if (dx <= 9 && dz <= 9 && dx + dz <= 13) {
        const h = api.heightAt(x, z);
        const yGround = Math.max(0, seatY + Math.round(h));
        for (let y = yGround; y <= seatY; y++) {
          set(x, y, z, plinth);
        }
      }
    }
  }

  // Pedestal Tier 1 (y = 4..5)
  for (let x = 2; x <= 20; x++) {
    for (let z = 3; z <= 21; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      if (dx <= 9 && dz <= 9 && dx + dz <= 13) {
        set(x, 4, z, plinth);
        if (dx <= 8 && dz <= 8 && dx + dz <= 12) {
          set(x, 5, z, quartzBrick);
        }
      }
    }
  }

  // Pedestal Tier 2 (y = 6)
  for (let x = 3; x <= 19; x++) {
    for (let z = 4; z <= 20; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      if (dx <= 8 && dz <= 8 && dx + dz <= 11) {
        set(x, 6, z, smoothQuartz);
      }
    }
  }

  // Pedestal Tier 3: Main Plinth Core (y = 7..9)
  for (let x = 4; x <= 18; x++) {
    for (let z = 5; z <= 19; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      if (dx <= 7 && dz <= 7 && dx + dz <= 10) {
        for (let y = 7; y <= 9; y++) {
          set(x, y, z, quartzBrick);
        }
      }
    }
  }

  // Arcane Ward Inlays on 4 Cardinal Faces of the Pedestal
  // North face (aimed at pirate coast across the strait)
  set(11, 8, 5, seaLantern);
  set(10, 8, 5, cryingObsidian);
  set(12, 8, 5, cryingObsidian);
  set(11, 7, 5, amethyst);
  set(11, 9, 5, amethyst);
  set(11, 8, 6, seaLantern);

  // South face
  set(11, 8, 19, seaLantern);
  set(10, 8, 19, cryingObsidian);
  set(12, 8, 19, cryingObsidian);
  set(11, 7, 19, amethyst);
  set(11, 9, 19, amethyst);

  // East face
  set(18, 8, 12, seaLantern);
  set(18, 8, 11, cryingObsidian);
  set(18, 8, 13, cryingObsidian);
  set(18, 7, 12, amethyst);
  set(18, 9, 12, amethyst);

  // West face
  set(4, 8, 12, seaLantern);
  set(4, 8, 11, cryingObsidian);
  set(4, 8, 13, cryingObsidian);
  set(4, 7, 12, amethyst);
  set(4, 9, 12, amethyst);

  // Pedestal Tier 4: Upper Cornice & Dais Top (y = 10..11)
  for (let x = 5; x <= 17; x++) {
    for (let z = 6; z <= 18; z++) {
      const dx = Math.abs(x - cx);
      const dz = Math.abs(z - cz);
      if (dx <= 6 && dz <= 6 && dx + dz <= 9) {
        set(x, 10, z, smoothQuartz);
      }
      if (dx <= 5 && dz <= 5 && dx + dz <= 8) {
        set(x, 11, z, smoothQuartz);
      }
    }
  }

  // Arcane Circle on Dais Top
  set(11, 11, 12, seaLantern);
  for (let angle = 0; angle < Math.PI * 2; angle += Math.PI / 4) {
    const rx = Math.round(cx + Math.cos(angle) * 2);
    const rz = Math.round(cz + Math.sin(angle) * 2);
    set(rx, 11, rz, amethyst);
    const gx = Math.round(cx + Math.cos(angle) * 3.2);
    const gz = Math.round(cz + Math.sin(angle) * 3.2);
    set(gx, 11, gz, gold);
  }

  // 4 Corner Wardstone Beacons (y = 6..13)
  const beaconCorners = [
    [5, 6],
    [17, 6],
    [5, 18],
    [17, 18],
  ];
  for (const [bx, bz] of beaconCorners) {
    for (let y = 6; y <= 8; y++) set(bx, y, bz, quartzPillar);
    set(bx, 9, bz, gold);
    set(bx, 10, bz, seaLantern);
    set(bx, 11, bz, tintedGlass);
    set(bx, 12, bz, amethyst);
    setCluster(bx, 13, bz, "up");
    setCluster(bx + 1, 10, bz, "east");
    setCluster(bx - 1, 10, bz, "west");
    setCluster(bx, 10, bz + 1, "south");
    setCluster(bx, 10, bz - 1, "north");
  }

  // --- 2. REARING UNICORN ANATOMY ---

  // Hind Hooves & Lower Legs (firmly rooted to dais at y = 11)
  // Left Hind Hoof
  set(8, 11, 15, gold);
  set(9, 11, 15, gold);
  set(8, 11, 16, gold);
  set(9, 11, 16, gold);
  set(8, 12, 15, gold);
  set(9, 12, 15, gold);

  // Right Hind Hoof
  set(13, 11, 15, gold);
  set(14, 11, 15, gold);
  set(13, 11, 16, gold);
  set(14, 11, 16, gold);
  set(13, 12, 15, gold);
  set(14, 12, 15, gold);

  // Hind Cannons & Gaskins
  fillTaperedCapsule(8.5, 12.0, 15.5, 1.2, 8.5, 16.0, 16.5, 1.3, smoothQuartz);
  fillTaperedCapsule(13.5, 12.0, 15.5, 1.2, 13.5, 16.0, 16.5, 1.3, smoothQuartz);

  // Hind Thighs (powerful rearing muscular haunches)
  fillTaperedCapsule(8.5, 16.0, 16.5, 1.5, 9.0, 20.0, 14.0, 2.0, smoothQuartz);
  fillTaperedCapsule(13.5, 16.0, 16.5, 1.5, 13.0, 20.0, 14.0, 2.0, smoothQuartz);

  // Pelvis / Rump
  fillEllipsoid(11.0, 20.0, 14.5, 3.2, 2.6, 2.6, smoothQuartz);

  // Rearing Barrel & Ribcage (angled up towards North, -Z)
  fillEllipsoid(11.0, 22.5, 12.5, 3.0, 2.8, 2.8, smoothQuartz);
  fillEllipsoid(11.0, 25.5, 10.5, 3.2, 3.0, 2.9, smoothQuartz);
  fillEllipsoid(11.0, 28.0, 8.5, 3.1, 3.2, 2.9, smoothQuartz);

  // Broad Pectorals & Sternum
  fillEllipsoid(11.0, 27.5, 7.0, 2.3, 2.1, 1.9, smoothQuartz);

  // Rearing Front Legs (striking high in the air)
  // Left Front Leg
  fillTaperedCapsule(8.0, 27.5, 8.5, 1.4, 7.0, 29.5, 6.0, 1.2, smoothQuartz);
  fillTaperedCapsule(7.0, 29.5, 6.0, 1.2, 7.0, 26.0, 4.0, 1.0, smoothQuartz);
  // Left Hoof
  set(7, 25, 4, gold);
  set(7, 25, 3, gold);
  set(6, 25, 4, gold);

  // Right Front Leg (rearing even higher in dramatic asymmetric pose)
  fillTaperedCapsule(14.0, 27.5, 8.5, 1.4, 14.5, 31.0, 6.5, 1.2, smoothQuartz);
  fillTaperedCapsule(14.5, 31.0, 6.5, 1.2, 14.5, 29.5, 3.5, 1.0, smoothQuartz);
  // Right Hoof
  set(14, 29, 3, gold);
  set(15, 29, 3, gold);
  set(14, 29, 2, gold);

  // Arched Neck
  fillEllipsoid(11.0, 30.0, 7.2, 2.4, 2.3, 2.3, smoothQuartz);
  fillEllipsoid(11.0, 32.8, 6.0, 2.1, 2.2, 2.1, smoothQuartz);
  fillEllipsoid(11.0, 35.2, 5.2, 1.9, 1.9, 1.9, smoothQuartz);

  // Head & Jaw
  fillEllipsoid(11.0, 36.5, 4.5, 1.8, 1.7, 1.8, smoothQuartz);
  fillEllipsoid(11.0, 35.5, 4.0, 1.6, 1.5, 1.6, smoothQuartz);

  // Muzzle & Snout (reaching forward to -Z)
  fillEllipsoid(11.0, 35.0, 2.2, 1.3, 1.2, 1.5, smoothQuartz);
  set(10, 34, 1, smoothQuartz);
  set(12, 34, 1, smoothQuartz);
  set(11, 34, 1, smoothQuartz);

  // Radiant Celestial Eyes
  set(9, 36, 4, seaLantern);
  set(13, 36, 4, seaLantern);

  // Pointed Ears
  set(9, 38, 5, smoothQuartz);
  set(9, 39, 6, smoothQuartz);
  set(13, 38, 5, smoothQuartz);
  set(13, 39, 6, smoothQuartz);

  // --- 3. THE GLOWING CELESTIAL HORN (Aimed across the strait at -Z) ---
  set(11, 37, 4, amethyst);
  set(11, 37, 3, gold);
  set(11, 38, 2, seaLantern);
  set(11, 38, 1, amethyst);
  set(11, 39, 0, "minecraft:end_rod[facing=north]");

  // Crystal crown & radiant bursts flanking the horn
  setCluster(10, 38, 2, "west");
  setCluster(12, 38, 2, "east");
  setCluster(11, 39, 2, "up");
  setCluster(11, 37, 2, "down");
  setCluster(10, 38, 1, "west");
  setCluster(12, 38, 1, "east");

  // --- 4. FLOWING AMETHYST MANE ---
  const maneSpine = [
    [11, 37, 5.5],
    [11, 36, 6.5],
    [11, 34, 7.5],
    [11, 32, 8.5],
    [11, 30, 9.2],
    [11, 28, 9.8],
  ];
  for (const [mx, my, mz] of maneSpine) {
    set(mx, my, mz, amethyst);
    setCluster(mx, my + 1, mz, "up");
    set(mx - 1, my - 1, mz, amethyst);
    set(mx + 1, my - 1, mz, amethyst);
    setCluster(mx - 2, my - 1, mz, "west");
    setCluster(mx + 2, my - 1, mz, "east");
  }

  // --- 5. SWEEPING CELESTIAL WINGS (Swept back and outward) ---
  function cubicBezier(p0, p1, p2, p3, t) {
    const u = 1 - t;
    const tt = t * t, uu = u * u;
    const uuu = uu * u, ttt = tt * t;
    return [
      uuu * p0[0] + 3 * uu * t * p1[0] + 3 * u * tt * p2[0] + ttt * p3[0],
      uuu * p0[1] + 3 * uu * t * p1[1] + 3 * u * tt * p2[1] + ttt * p3[1],
      uuu * p0[2] + 3 * uu * t * p1[2] + 3 * u * tt * p2[2] + ttt * p3[2],
    ];
  }

  // Left Wing Main Spar Curve
  const leftWingP0 = [8.0, 28.0, 9.0];
  const leftWingP1 = [4.5, 32.0, 10.0];
  const leftWingP2 = [2.5, 36.5, 12.0];
  const leftWingP3 = [1.8, 39.0, 14.5];

  const steps = 8;
  for (let i = 0; i < steps; i++) {
    const t0 = i / steps;
    const t1 = (i + 1) / steps;
    const ptA = cubicBezier(leftWingP0, leftWingP1, leftWingP2, leftWingP3, t0);
    const ptB = cubicBezier(leftWingP0, leftWingP1, leftWingP2, leftWingP3, t1);
    const rA = 1.5 - t0 * 0.8;
    const rB = 1.5 - t1 * 0.8;

    // Left wing spar
    fillTaperedCapsule(ptA[0], ptA[1], ptA[2], rA, ptB[0], ptB[1], ptB[2], rB, smoothQuartz);
    // Right wing spar (mirrored)
    fillTaperedCapsule(22 - ptA[0], ptA[1], ptA[2], rA, 22 - ptB[0], ptB[1], ptB[2], rB, smoothQuartz);
  }

  // Feather Sweeps (Left & Right)
  const featherConfigs = [
    { orig: [1.8, 39.0, 14.5], dest: [2.8, 33.0, 18.0], r0: 0.9, r1: 0.5, mat: amethyst },
    { orig: [2.2, 37.0, 13.5], dest: [3.4, 30.0, 17.0], r0: 0.9, r1: 0.5, mat: smoothQuartz },
    { orig: [3.0, 35.0, 12.0], dest: [4.2, 28.0, 16.0], r0: 1.0, r1: 0.5, mat: smoothQuartz },
    { orig: [4.2, 32.5, 11.0], dest: [5.2, 26.5, 15.0], r0: 1.0, r1: 0.6, mat: smoothQuartz },
    { orig: [5.8, 30.5, 9.8],  dest: [6.8, 25.0, 13.5], r0: 1.1, r1: 0.7, mat: smoothQuartz },
    { orig: [7.0, 29.0, 9.3],  dest: [7.8, 24.5, 11.5], r0: 1.2, r1: 0.8, mat: smoothQuartz },
  ];

  for (let f = 0; f < featherConfigs.length; f++) {
    const { orig, dest, r0, r1, mat } = featherConfigs[f];
    fillTaperedCapsule(orig[0], orig[1], orig[2], r0, dest[0], dest[1], dest[2], r1, mat);
    fillTaperedCapsule(22 - orig[0], orig[1], orig[2], r0, 22 - dest[0], dest[1], dest[2], r1, mat);

    // Feather webbing cross-links
    if (f > 0) {
      const prev = featherConfigs[f - 1];
      const midA = [
        (orig[0] + dest[0]) * 0.5,
        (orig[1] + dest[1]) * 0.5,
        (orig[2] + dest[2]) * 0.5,
      ];
      const midB = [
        (prev.orig[0] + prev.dest[0]) * 0.5,
        (prev.orig[1] + prev.dest[1]) * 0.5,
        (prev.orig[2] + prev.dest[2]) * 0.5,
      ];
      fillCapsule(midA[0], midA[1], midA[2], midB[0], midB[1], midB[2], 0.8, smoothQuartz);
      fillCapsule(22 - midA[0], midA[1], midA[2], 22 - midB[0], midB[1], midB[2], 0.8, smoothQuartz);
    }
  }

  // Wing Tip Amethyst Clusters
  setCluster(1, 39, 15, "west");
  setCluster(21, 39, 15, "east");
  setCluster(2, 40, 14, "up");
  setCluster(20, 40, 14, "up");

  // --- 6. CASCADING TAIL (Structural Anchor to Pedestal) ---
  const tailP0 = [11.0, 20.0, 15.5];
  const tailP1 = [11.0, 22.5, 17.0];
  const tailP2 = [11.0, 16.0, 19.5];
  const tailP3 = [11.0, 11.0, 19.0];

  for (let i = 0; i < steps; i++) {
    const t0 = i / steps;
    const t1 = (i + 1) / steps;
    const ptA = cubicBezier(tailP0, tailP1, tailP2, tailP3, t0);
    const ptB = cubicBezier(tailP0, tailP1, tailP2, tailP3, t1);
    const rA = 1.3 + t0 * 0.5;
    const rB = 1.3 + t1 * 0.5;
    fillTaperedCapsule(ptA[0], ptA[1], ptA[2], rA, ptB[0], ptB[1], ptB[2], rB, smoothQuartz);
  }

  // Flaring locks of tail spreading on dais top
  fillTaperedCapsule(11.0, 12.0, 18.5, 1.4, 9.5, 11.0, 19.5, 1.2, amethyst);
  fillTaperedCapsule(11.0, 12.0, 18.5, 1.4, 12.5, 11.0, 19.5, 1.2, amethyst);
  setCluster(11, 14, 20, "south");
  setCluster(9, 11, 20, "south");
  setCluster(13, 11, 20, "south");
  setCluster(11, 18, 19, "south");

  // --- 7. EMIT GRID DETERMINISTICALLY ---
  for (let y = 0; y < H; y++) {
    for (let z = 0; z < D; z++) {
      for (let x = 0; x < W; x++) {
        const block = voxels[x][y][z];
        if (block !== null) {
          api.set(x, y, z, block);
        }
      }
    }
  }

  return {
    name: "Celestial Unicorn Monument",
    seatY: seatY,
    anchors: {
      front: [cx, seatY, 0],
    },
  };
}

shore_cannon.source:
export const envelope = [9, 9, 9];

export default function build(api) {
  const [W, H, D] = api.size;

  // Helper to safely apply or override block state properties
  function applyState(blockStr, stateObj) {
    if (!blockStr) return "minecraft:air";
    let base = blockStr;
    const existing = {};
    const bracketIndex = blockStr.indexOf('[');
    if (bracketIndex !== -1) {
      base = blockStr.substring(0, bracketIndex);
      const inside = blockStr.substring(bracketIndex + 1, blockStr.length - 1);
      inside.split(',').forEach(kv => {
        const [k, v] = kv.split('=');
        if (k && v) existing[k.trim()] = v.trim();
      });
    }
    const merged = Object.assign({}, existing, stateObj);
    const statePairs = Object.entries(merged).map(([k, v]) => `${k}=${v}`);
    if (statePairs.length === 0) return base;
    return `${base}[${statePairs.join(',')}]`;
  }

  // Safe setter with envelope bounds check
  function setBlock(x, y, z, blockStr) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, blockStr);
    }
  }

  // Theme block fallbacks
  const woodPlanks = api.theme?.wood?.planks || "minecraft:oak_planks";
  const woodLog = api.theme?.wood?.log || "minecraft:oak_log";
  const woodStripped = api.theme?.wood?.stripped || "minecraft:stripped_oak_log";
  const woodStairs = api.theme?.wood?.stairs || "minecraft:oak_stairs";
  const woodSlab = api.theme?.wood?.slab || "minecraft:oak_slab";
  const woodFence = api.theme?.wood?.fence || "minecraft:oak_fence";
  const woodTrapdoor = api.theme?.wood?.trapdoor || "minecraft:oak_trapdoor";

  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:cobblestone";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:cobblestone_wall";

  const groundPavement = api.theme?.ground?.pavement || "minecraft:cobblestone";
  const groundPlinth = api.theme?.ground?.plinth || "minecraft:stone_bricks";

  const roofSolid = api.theme?.roof?.solid || "minecraft:dark_oak_planks";
  const roofStairs = api.theme?.roof?.stairs || "minecraft:dark_oak_stairs";
  const roofSlab = api.theme?.roof?.slab || "minecraft:dark_oak_slab";

  // Per-instance determinism & variation
  const instanceSeed = api.instance.index;
  const superstructureStyle = instanceSeed % 3; // 0: Signal Mast, 1: Derrick Crane, 2: Fortified Casemate
  const cannonType = (instanceSeed + 1) % 3; // 0: Heavy Siege Drake, 1: Coastal Carronade, 2: Culverin
  const isWeathered = api.random() > 0.4;
  const shotPyramidSize = 3 + Math.floor(api.random() * 4); // 3 to 6 cannonballs

  // 1. FOUNDATION & SUB-SURFACE FILL (Rule 6: follow terrain downwards)
  for (let x = 0; x < 9; x++) {
    for (let z = 0; z < 9; z++) {
      const terrainH = api.heightAt(x, z);
      const minY = Math.min(0, Math.max(-4, terrainH));
      for (let y = minY; y <= 2; y++) {
        const isPerimeter = (x === 0 || x === 8 || z === 0 || z === 8);
        if (y < 2) {
          if (isPerimeter) {
            setBlock(x, y, z, ((x + z) % 2 === 0) ? stonePrimary : stoneAccent);
          } else {
            setBlock(x, y, z, groundPlinth);
          }
        } else {
          // y = 2: Gun Deck Flooring
          if (x >= 3 && x <= 5 && z <= 2) {
            // Reinforced stone gun track
            setBlock(x, y, z, stonePrimary);
          } else if (z === 8 && (x === 3 || x === 4 || x === 5)) {
            // Rear steps access
            setBlock(x, y, z, applyState(stoneStairs, { facing: "south", half: "bottom" }));
          } else if (isPerimeter) {
            setBlock(x, y, z, applyState(woodLog, { axis: (x === 0 || x === 8) ? "z" : "x" }));
          } else {
            setBlock(x, y, z, (isWeathered && api.random() > 0.7) ? stoneAccent : woodPlanks);
          }
        }
      }
    }
  }

  // 2. PARAPETS & REVETMENT WALLS (y = 3 to 5)
  // Corner upright log bastions
  const corners = [[0, 0], [8, 0], [0, 8], [8, 8]];
  corners.forEach(([cx, cz]) => {
    for (let y = 3; y <= 4; y++) {
      setBlock(cx, y, cz, applyState(woodLog, { axis: "y" }));
    }
    setBlock(cx, 5, cz, applyState(woodSlab, { type: "bottom" }));
  });

  // Front sea-facing revetment (z = 0, 1) with gun embrasure at x = 3..5
  for (let x = 0; x < 9; x++) {
    for (let z = 0; z <= 1; z++) {
      if ((x >= 0 && x <= 2) || (x >= 6 && x <= 8)) {
        // Solid embrasure cheeks / cheeks
        setBlock(x, 3, z, (z === 0) ? applyState(woodLog, { axis: "y" }) : stonePrimary);
        setBlock(x, 4, z, (x === 1 || x === 7) ? stoneWall : applyState(woodLog, { axis: "x" }));
        if (z === 0) {
          setBlock(x, 5, z, applyState(stoneSlab, { type: "bottom" }));
        }
      }
    }
  }

  // Embrasure splay cheeks
  setBlock(3, 3, 0, applyState(stoneStairs, { facing: "east", half: "bottom" }));
  setBlock(3, 3, 1, applyState(woodLog, { axis: "y" }));
  setBlock(5, 3, 0, applyState(stoneStairs, { facing: "west", half: "bottom" }));
  setBlock(5, 3, 1, applyState(woodLog, { axis: "y" }));
  setBlock(3, 4, 0, stoneWall);
  setBlock(5, 4, 0, stoneWall);

  // Side breastwork walls (x = 0 and x = 8, z = 2..7)
  for (let z = 2; z <= 7; z++) {
    // West flank (x = 0)
    setBlock(0, 3, z, applyState(woodLog, { axis: "y" }));
    setBlock(0, 4, z, (z % 2 === 0) ? stoneWall : applyState(woodTrapdoor, { facing: "east", open: "true" }));
    if (z % 2 === 1) setBlock(0, 5, z, applyState(woodSlab, { type: "bottom" }));

    // East flank (x = 8)
    setBlock(8, 3, z, applyState(woodLog, { axis: "y" }));
    setBlock(8, 4, z, (z % 2 === 0) ? stoneWall : applyState(woodTrapdoor, { facing: "west", open: "true" }));
    if (z % 2 === 1) setBlock(8, 5, z, applyState(woodSlab, { type: "bottom" }));
  }

  // Rear retaining parapet (z = 8, x = 0..2 and x = 6..8)
  for (let x = 0; x <= 2; x++) {
    setBlock(x, 3, 8, stonePrimary);
    setBlock(x, 4, 8, woodFence);
  }
  for (let x = 6; x <= 8; x++) {
    setBlock(x, 3, 8, stonePrimary);
    setBlock(x, 4, 8, woodFence);
  }

  // 3. THE SHORE CANNON (Facing North: -Z)
  if (cannonType === 0) {
    // Heavy 32-Pounder Siege Drake (Long Gun)
    // Wheels & Carriage
    setBlock(3, 3, 2, applyState(woodStripped, { axis: "z" }));
    setBlock(3, 3, 4, applyState(woodStripped, { axis: "z" }));
    setBlock(5, 3, 2, applyState(woodStripped, { axis: "z" }));
    setBlock(5, 3, 4, applyState(woodStripped, { axis: "z" }));

    setBlock(2, 3, 2, "minecraft:dark_oak_trapdoor[facing=west,half=bottom,open=true]");
    setBlock(2, 3, 4, "minecraft:dark_oak_trapdoor[facing=west,half=bottom,open=true]");
    setBlock(6, 3, 2, "minecraft:dark_oak_trapdoor[facing=east,half=bottom,open=true]");
    setBlock(6, 3, 4, "minecraft:dark_oak_trapdoor[facing=east,half=bottom,open=true]");

    // Gun Bed & Breech
    setBlock(4, 3, 4, "minecraft:polished_blackstone");
    setBlock(4, 3, 3, "minecraft:polished_blackstone");
    setBlock(4, 3, 2, "minecraft:netherite_block");
    setBlock(4, 3, 1, "minecraft:dispenser[facing=north]");
    setBlock(4, 3, 0, "minecraft:grindstone[facing=north]");

    // Top sights & iron bands
    setBlock(4, 4, 3, "minecraft:polished_blackstone_slab[type=bottom]");
    setBlock(4, 4, 2, "minecraft:heavy_weighted_pressure_plate");
    setBlock(4, 4, 1, "minecraft:lever[facing=north,powered=false]");

    // Recoil tackle ropes/chains
    setBlock(3, 3, 5, "minecraft:chain[axis=z]");
    setBlock(5, 3, 5, "minecraft:chain[axis=z]");

  } else if (cannonType === 1) {
    // Heavy Coastal Carronade / Mortar
    // Stout timber platform
    setBlock(3, 3, 3, applyState(woodStripped, { axis: "x" }));
    setBlock(4, 3, 3, "minecraft:lodestone");
    setBlock(5, 3, 3, applyState(woodStripped, { axis: "x" }));

    setBlock(2, 3, 3, "minecraft:dark_oak_trapdoor[facing=west,half=bottom,open=true]");
    setBlock(6, 3, 3, "minecraft:dark_oak_trapdoor[facing=east,half=bottom,open=true]");

    // Angled heavy bore
    setBlock(4, 3, 2, "minecraft:polished_blackstone");
    setBlock(4, 3, 1, "minecraft:dispenser[facing=north]");
    setBlock(4, 4, 2, "minecraft:cauldron");
    setBlock(4, 4, 3, "minecraft:polished_blackstone_slab[type=bottom]");
    setBlock(3, 4, 2, "minecraft:anvil[facing=north]");
    setBlock(5, 4, 2, "minecraft:anvil[facing=north]");

  } else {
    // Reinforced Double Culverin
    setBlock(3, 3, 3, applyState(woodStripped, { axis: "z" }));
    setBlock(5, 3, 3, applyState(woodStripped, { axis: "z" }));
    setBlock(4, 3, 3, "minecraft:polished_blackstone");

    setBlock(3, 3, 2, "minecraft:dispenser[facing=north]");
    setBlock(5, 3, 2, "minecraft:dispenser[facing=north]");
    setBlock(3, 3, 1, "minecraft:polished_blackstone_wall");
    setBlock(5, 3, 1, "minecraft:polished_blackstone_wall");

    setBlock(2, 3, 3, "minecraft:dark_oak_trapdoor[facing=west,half=bottom,open=true]");
    setBlock(6, 3, 3, "minecraft:dark_oak_trapdoor[facing=east,half=bottom,open=true]");

    setBlock(4, 4, 3, "minecraft:polished_blackstone_slab[type=bottom]");
    setBlock(4, 3, 4, "minecraft:barrel[facing=north]");
  }

  // 4. BATTERY DETAILS & SHOT PILES
  // Left Bay (x = 1..2, z = 3..6): Powder & Shot
  setBlock(1, 3, 5, "minecraft:barrel[facing=up]");
  setBlock(2, 3, 6, "minecraft:barrel[facing=up]");
  setBlock(1, 3, 6, applyState(woodPlanks, {}));
  setBlock(1, 4, 6, "minecraft:lantern[hanging=false]");

  // Shot pile (cannonballs)
  setBlock(1, 3, 3, "minecraft:wither_skeleton_skull[rotation=0]");
  if (shotPyramidSize >= 4) setBlock(1, 3, 4, "minecraft:wither_skeleton_skull[rotation=4]");
  if (shotPyramidSize >= 5) setBlock(2, 3, 3, "minecraft:wither_skeleton_skull[rotation=8]");
  if (shotPyramidSize >= 6) setBlock(2, 3, 4, "minecraft:wither_skeleton_skull[rotation=12]");

  // Right Bay (x = 6..7, z = 3..6): Tools & Swabbing Station
  setBlock(7, 3, 3, "minecraft:cauldron");
  setBlock(7, 3, 4, woodFence);
  setBlock(7, 4, 4, "minecraft:tripwire_hook[facing=west,attached=false]");
  setBlock(7, 3, 5, "minecraft:barrel[facing=north]");
  setBlock(6, 3, 6, applyState(woodPlanks, {}));

  // 5. SUPERSTRUCTURE & VERTICAL SILHOUETTES (y = 5 to 8)
  if (superstructureStyle === 0) {
    // Style 0: Pirate Lookout Mast & Signal Pennant
    // Mast upright
    for (let y = 3; y <= 8; y++) {
      setBlock(7, y, 7, applyState(woodLog, { axis: "y" }));
      if (y >= 3 && y <= 6) {
        setBlock(7, y, 6, "minecraft:ladder[facing=north]");
      }
    }

    // Crow's nest platform at y = 6
    setBlock(6, 6, 7, applyState(woodTrapdoor, { facing: "west", half: "top", open: "false" }));
    setBlock(8, 6, 7, applyState(woodTrapdoor, { facing: "east", half: "top", open: "false" }));
    setBlock(7, 6, 8, applyState(woodTrapdoor, { facing: "south", half: "top", open: "false" }));

    // Yardarm cross-beam at y = 7
    setBlock(6, 7, 7, woodFence);
    setBlock(8, 7, 7, woodFence);
    setBlock(6, 6, 7, "minecraft:lantern[hanging=true]");

    // Pirate Pennant at masthead (y = 8, waving toward front-left)
    setBlock(7, 8, 6, "minecraft:black_wool");
    setBlock(7, 8, 5, "minecraft:red_wool");
    setBlock(7, 7, 5, "minecraft:white_wool");

    // Left lean-to canopy over powder (x = 0..3, z = 5..7)
    setBlock(1, 3, 7, applyState(woodLog, { axis: "y" }));
    setBlock(1, 4, 7, applyState(woodLog, { axis: "y" }));
    setBlock(1, 5, 7, applyState(woodLog, { axis: "y" }));
    setBlock(0, 5, 6, applyState(roofStairs, { facing: "north", half: "bottom" }));
    setBlock(1, 5, 6, applyState(roofStairs, { facing: "north", half: "bottom" }));
    setBlock(2, 5, 6, applyState(roofStairs, { facing: "north", half: "bottom" }));
    setBlock(1, 6, 7, applyState(roofSlab, { type: "bottom" }));
    setBlock(2, 6, 7, applyState(roofSlab, { type: "bottom" }));

  } else if (superstructureStyle === 1) {
    // Style 1: Heavy Derrick Shot Crane & Gantry
    // Crane main mast at x = 2, z = 7
    for (let y = 3; y <= 7; y++) {
      setBlock(2, y, 7, applyState(woodLog, { axis: "y" }));
    }

    // Jib arm reaching up & over gun (x = 2..4, z = 7..3)
    setBlock(2, 6, 6, woodFence);
    setBlock(3, 7, 5, woodFence);
    setBlock(3, 7, 4, woodFence);
    setBlock(4, 8, 3, woodFence);

    // Hoist line and suspended heavy iron shot
    setBlock(4, 7, 3, "minecraft:chain[axis=y]");
    setBlock(4, 6, 3, "minecraft:chain[axis=y]");
    setBlock(4, 5, 3, "minecraft:polished_blackstone");

    // Right-side guard shelter and lantern pole
    for (let y = 3; y <= 6; y++) {
      setBlock(7, y, 7, applyState(woodLog, { axis: "y" }));
    }
    setBlock(7, 7, 7, stoneWall);
    setBlock(7, 8, 7, "minecraft:lantern[hanging=false]");

    setBlock(6, 5, 7, applyState(woodSlab, { type: "top" }));
    setBlock(8, 5, 7, applyState(woodSlab, { type: "top" }));
    setBlock(6, 4, 7, "minecraft:lantern[hanging=true]");

  } else {
    // Style 2: Fortified Coastal Casemate Roof & Signal Beacon
    // Log posts
    const postCoords = [[1, 2], [7, 2], [1, 7], [7, 7]];
    postCoords.forEach(([px, pz]) => {
      for (let y = 3; y <= 5; y++) {
        setBlock(px, y, pz, applyState(woodLog, { axis: "y" }));
      }
    });

    // Cross-beams at y = 5
    for (let x = 1; x <= 7; x++) {
      setBlock(x, 5, 2, applyState(woodLog, { axis: "x" }));
      setBlock(x, 5, 7, applyState(woodLog, { axis: "x" }));
    }
    for (let z = 2; z <= 7; z++) {
      setBlock(1, 5, z, applyState(woodLog, { axis: "z" }));
      setBlock(7, 5, z, applyState(woodLog, { axis: "z" }));
    }

    // Timber pitched roof (slopes down to north and south)
    for (let x = 1; x <= 7; x++) {
      setBlock(x, 6, 2, applyState(roofStairs, { facing: "south", half: "bottom" }));
      setBlock(x, 6, 3, applyState(roofStairs, { facing: "south", half: "bottom" }));
      setBlock(x, 7, 4, roofSolid);
      setBlock(x, 7, 5, roofSolid);
      setBlock(x, 6, 6, applyState(roofStairs, { facing: "north", half: "bottom" }));
      setBlock(x, 6, 7, applyState(roofStairs, { facing: "north", half: "bottom" }));
    }

    // Signal Beacon on roof ridge
    setBlock(4, 8, 4, stoneWall);
    setBlock(4, 8, 5, stoneWall);
    setBlock(4, 9, 4, "minecraft:lantern[hanging=false]"); // Clamped safely if H=9

    // Hanging chandelier / lantern over gun
    setBlock(4, 5, 3, "minecraft:chain[axis=y]");
    setBlock(4, 4, 3, "minecraft:lantern[hanging=true]");
  }

  return {
    name: "shore_cannon",
    seatY: 0,
    anchors: {
      front: [4, 2, 0], // Embrasure looking north toward the enemy strait
      door: [4, 2, 8],  // Rear battery access steps
    },
  };
}

wardstone_crystal.source:
export const envelope = [11, 18, 11];

export default function build(api) {
  const W = 11, H = 18, D = 11;
  const cx = 5, cz = 5;
  const SEAT_Y = 3;

  const variant = (api.instance.index || 0) % 6;
  const rng = () => api.random();

  // Theme palette extraction with robust defaults
  const stonePrimary = api.theme?.stone?.primary || "minecraft:smooth_quartz";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:chiseled_quartz_block";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:smooth_quartz_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:smooth_quartz_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:diorite_wall";
  const groundPlinth = api.theme?.ground?.plinth || "minecraft:quartz_pillar";
  const groundPavement = api.theme?.ground?.pavement || "minecraft:quartz_bricks";

  // Arcane crystalline materials
  const amethystBlock = "minecraft:amethyst_block";
  const buddingAmethyst = "minecraft:budding_amethyst";
  const cryingObsidian = "minecraft:crying_obsidian";
  const seaLantern = "minecraft:sea_lantern";
  const calcite = "minecraft:calcite";
  const tintedGlass = "minecraft:tinted_glass";

  // Grid buffer
  const grid = Array.from({ length: W }, () =>
    Array.from({ length: H }, () =>
      new Array(D).fill(null)
    )
  );

  function put(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D && block) {
      grid[x][y][z] = block;
    }
  }

  function get(x, y, z) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      return grid[x][y][z];
    }
    return null;
  }

  function isSolid(x, y, z) {
    const b = get(x, y, z);
    if (!b) return false;
    if (b.includes("air") || b.includes("cluster") || b.includes("bud")) return false;
    return true;
  }

  function getStair(facing, half = "bottom", shape = "straight") {
    const base = stoneStairs.split("[")[0];
    return `${base}[facing=${facing},half=${half},shape=${shape}]`;
  }

  function getSlab(type = "bottom") {
    const base = stoneSlab.split("[")[0];
    return `${base}[type=${type}]`;
  }

  function getPillar(axis = "y") {
    return `minecraft:quartz_pillar[axis=${axis}]`;
  }

  function getCluster(facing, size = 3) {
    const names = [
      "minecraft:small_amethyst_bud",
      "minecraft:medium_amethyst_bud",
      "minecraft:large_amethyst_bud",
      "minecraft:amethyst_cluster"
    ];
    const name = names[Math.max(0, Math.min(3, Math.floor(size)))];
    return `${name}[facing=${facing}]`;
  }

  function getOutwardStair(dx, dz, half = "bottom") {
    let facing = "north";
    if (Math.abs(dx) > Math.abs(dz)) {
      facing = dx > 0 ? "east" : "west";
    } else {
      facing = dz > 0 ? "south" : "north";
    }
    return getStair(facing, half);
  }

  function getInwardStair(dx, dz, half = "bottom") {
    let facing = "south";
    if (Math.abs(dx) > Math.abs(dz)) {
      facing = dx > 0 ? "west" : "east";
    } else {
      facing = dz > 0 ? "north" : "south";
    }
    return getStair(facing, half);
  }

  function tryAttachCluster(x, y, z, preferredDir, size = 3) {
    if (x < 0 || x >= W || y < 0 || y >= H || z < 0 || z >= D) return false;
    if (get(x, y, z) !== null) return false;

    const attachments = {
      up: [0, -1, 0],
      down: [0, 1, 0],
      north: [0, 0, 1],
      south: [0, 0, -1],
      east: [-1, 0, 0],
      west: [1, 0, 0]
    };

    if (preferredDir && attachments[preferredDir]) {
      const [adx, ady, adz] = attachments[preferredDir];
      if (isSolid(x + adx, y + ady, z + adz)) {
        put(x, y, z, getCluster(preferredDir, size));
        return true;
      }
    }

    for (const [dir, [adx, ady, adz]] of Object.entries(attachments)) {
      if (isSolid(x + adx, y + ady, z + adz)) {
        put(x, y, z, getCluster(dir, size));
        return true;
      }
    }
    return false;
  }

  // -------------------------------------------------------------
  // 1. BASE FOUNDATION & STEPPED PLINTH (y = 0 to 6)
  // -------------------------------------------------------------

  // Downward ground skirt following terrain
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx;
      const dz = z - cz;
      const distSq = dx * dx + dz * dz;
      if (distSq <= 20.25) {
        const h = api.heightAt(x, z);
        const groundY = Math.max(0, Math.min(SEAT_Y, SEAT_Y + h));
        for (let y = groundY; y < SEAT_Y; y++) {
          put(x, y, z, distSq <= 8 ? groundPlinth : groundPavement);
        }
      }
    }
  }

  // Tier 0: Ground Platform (y = 3)
  for (let x = 0; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const dx = x - cx, dz = z - cz;
      const distSq = dx * dx + dz * dz;
      if (distSq <= 20.25) {
        if (distSq > 15.0) {
          put(x, 3, z, getOutwardStair(dx, dz, "bottom"));
        } else if (distSq > 8.5) {
          put(x, 3, z, groundPavement);
        } else {
          put(x, 3, z, stonePrimary);
        }
      }
    }
  }
  // Cardinal accents on platform
  put(cx, 3, cz - 4, stoneAccent);
  put(cx, 3, cz + 4, stoneAccent);
  put(cx - 4, 3, cz, stoneAccent);
  put(cx + 4, 3, cz, stoneAccent);

  // Tier 1: Middle Terrace (y = 4)
  for (let x = 1; x < W - 1; x++) {
    for (let z = 1; z < D - 1; z++) {
      const dx = x - cx, dz = z - cz;
      const distSq = dx * dx + dz * dz;
      if (distSq <= 13.0) {
        if (distSq > 8.0) {
          put(x, 4, z, getOutwardStair(dx, dz, "bottom"));
        } else {
          put(x, 4, z, stonePrimary);
        }
      }
    }
  }
  // Corner socket energy stones
  const cornerSockets = [[2, 4, 2], [8, 4, 2], [2, 4, 8], [8, 4, 8]];
  for (const [sx, sy, sz] of cornerSockets) {
    put(sx, sy, sz, variant % 2 === 0 ? cryingObsidian : amethystBlock);
  }

  // Tier 2: Upper Plinth Socket (y = 5)
  for (let dx = -2; dx <= 2; dx++) {
    for (let dz = -2; dz <= 2; dz++) {
      const distSq = dx * dx + dz * dz;
      if (distSq <= 8.0) {
        if (distSq > 4.5) {
          put(cx + dx, 5, cz + dz, getOutwardStair(dx, dz, "bottom"));
        } else {
          put(cx + dx, 5, cz + dz, stoneAccent);
        }
      }
    }
  }

  // Tier 3: Spire Collar (y = 6)
  for (let dx = -1; dx <= 1; dx++) {
    for (let dz = -1; dz <= 1; dz++) {
      if (dx === 0 && dz === 0) {
        put(cx, 6, cz, seaLantern);
      } else if (Math.abs(dx) === 1 && Math.abs(dz) === 1) {
        put(cx + dx, 6, cz + dz, getInwardStair(dx, dz, "bottom"));
      } else {
        put(cx + dx, 6, cz + dz, stonePrimary);
      }
    }
  }

  // -------------------------------------------------------------
  // 2. VARIANT SUPERSTRUCTURES (y = 7 to 17)
  // -------------------------------------------------------------

  if (variant === 0) {
    // -----------------------------------------------------------
    // VARIANT 0: "The Celestial Spire"
    // Tall slender needle, cardinal fin buttresses, amethyst crown
    // -----------------------------------------------------------
    for (let y = 7; y <= 14; y++) {
      // Core shaft
      put(cx, y, cz, y % 3 === 2 ? seaLantern : (y % 2 === 0 ? amethystBlock : calcite));
      put(cx + 1, y, cz, getPillar("y"));
      put(cx - 1, y, cz, getPillar("y"));
      put(cx, y, cz + 1, getPillar("y"));
      put(cx, y, cz - 1, getPillar("y"));

      // Helical crying obsidian runes at corners
      const cornerIdx = (y) % 4;
      const corners = [[cx - 1, cz - 1], [cx + 1, cz - 1], [cx + 1, cz + 1], [cx - 1, cz + 1]];
      for (let i = 0; i < 4; i++) {
        const [kdx, kdz] = corners[i];
        put(kdx, y, kdz, i === cornerIdx ? cryingObsidian : (y <= 10 ? stonePrimary : stoneAccent));
      }
    }

    // Cardinal Buttress Fins (y=7..11)
    const cardinalFins = [
      { dir: "north", x: cx, z: cz - 2, sx: cx, sz: cz - 3 },
      { dir: "south", x: cx, z: cz + 2, sx: cx, sz: cz + 3 },
      { dir: "east", x: cx + 2, z: cz, sx: cx + 3, sz: cz },
      { dir: "west", x: cx - 2, z: cz, sx: cx - 3, sz: cz }
    ];

    for (const fin of cardinalFins) {
      put(fin.x, 7, fin.z, stonePrimary);
      put(fin.x, 8, fin.z, getPillar("y"));
      put(fin.x, 9, fin.z, getStair(fin.dir, "bottom"));
      put(fin.sx, 7, fin.sz, getStair(fin.dir, "bottom"));
      put(fin.sx, 8, fin.sz, getSlab("bottom"));
    }
    // North focusing lens
    put(cx, 8, cz - 2, seaLantern);

    // Crown Tier (y=15..17)
    put(cx, 15, cz, seaLantern);
    put(cx + 1, 15, cz, getStair("east", "top"));
    put(cx - 1, 15, cz, getStair("west", "top"));
    put(cx, 15, cz + 1, getStair("south", "top"));
    put(cx, 15, cz - 1, getStair("north", "top"));

    put(cx, 16, cz, amethystBlock);
    put(cx + 1, 16, cz, stoneWall);
    put(cx - 1, 16, cz, stoneWall);
    put(cx, 16, cz + 1, stoneWall);
    put(cx, 16, cz - 1, stoneWall);

    put(cx, 17, cz, amethystBlock);

  } else if (variant === 1) {
    // -----------------------------------------------------------
    // VARIANT 1: "The Arcane Geode Monolith"
    // Hollow cracked geode core with visible floating sea lantern
    // -----------------------------------------------------------
    for (let y = 7; y <= 13; y++) {
      // Hollow crystalline geode chamber at y=8..11
      if (y >= 8 && y <= 11) {
        put(cx, y, cz, y === 9 ? seaLantern : null); // Floating central light
        put(cx + 1, y, cz, buddingAmethyst);
        put(cx - 1, y, cz, buddingAmethyst);
        put(cx, y, cz + 1, cryingObsidian);
        // North face open fissure
        put(cx, y, cz - 1, y === 9 ? null : getStair("north", "bottom"));

        put(cx - 1, y, cz - 1, stonePrimary);
        put(cx + 1, y, cz - 1, stonePrimary);
        put(cx - 1, y, cz + 1, amethystBlock);
        put(cx + 1, y, cz + 1, amethystBlock);
      } else {
        put(cx, y, cz, y === 7 ? seaLantern : calcite);
        for (let dx = -1; dx <= 1; dx++) {
          for (let dz = -1; dz <= 1; dz++) {
            if (dx !== 0 || dz !== 0) {
              put(cx + dx, y, cz + dz, stonePrimary);
            }
          }
        }
      }
    }

    // Diagonal Winged Pillars (NW, NE, SW, SE)
    const diagPillars = [
      [cx - 2, cz - 2], [cx + 2, cz - 2], [cx - 2, cz + 2], [cx + 2, cz + 2]
    ];
    for (const [px, pz] of diagPillars) {
      put(px, 7, pz, stonePrimary);
      put(px, 8, pz, getPillar("y"));
      put(px, 9, pz, stoneWall);
      put(px, 10, pz, amethystBlock);
    }

    // Geode Crown (y=14..16)
    put(cx, 14, cz, seaLantern);
    put(cx, 14, cz - 1, amethystBlock);
    put(cx, 14, cz + 1, amethystBlock);
    put(cx - 1, 14, cz, amethystBlock);
    put(cx + 1, 14, cz, cryingObsidian);

    put(cx, 15, cz, amethystBlock);
    put(cx, 15, cz - 1, amethystBlock); // Tall North spire
    put(cx, 15, cz + 1, cryingObsidian);
    put(cx - 1, 15, cz, stoneWall);
    put(cx + 1, 15, cz, stoneWall);

    put(cx, 16, cz - 1, amethystBlock);
    put(cx, 16, cz, amethystBlock);

  } else if (variant === 2) {
    // -----------------------------------------------------------
    // VARIANT 2: "The Quad-Prism Focusing Battery"
    // 4 satellite crystal pylons + central orb & flying arches
    // -----------------------------------------------------------
    // Central Power Column
    for (let y = 7; y <= 15; y++) {
      put(cx, y, cz, (y === 8 || y === 11 || y === 14) ? seaLantern : amethystBlock);
      put(cx + 1, y, cz, y <= 13 ? getPillar("y") : stoneWall);
      put(cx - 1, y, cz, y <= 13 ? getPillar("y") : stoneWall);
      put(cx, y, cz + 1, y <= 13 ? getPillar("y") : stoneWall);
      put(cx, y, cz - 1, y <= 13 ? getPillar("y") : stoneWall);
    }

    // 4 Satellite Pylons at (cx±2, cz±2)
    const pylons = [
      [cx - 2, cz - 2], [cx + 2, cz - 2], [cx - 2, cz + 2], [cx + 2, cz + 2]
    ];
    for (const [px, pz] of pylons) {
      for (let y = 7; y <= 12; y++) {
        if (y === 8) {
          put(px, y, pz, seaLantern);
        } else if (y === 11) {
          put(px, y, pz, stoneAccent);
        } else if (y === 12) {
          put(px, y, pz, amethystBlock);
        } else {
          put(px, y, pz, getPillar("y"));
        }
      }
    }

    // Arch Bridges connecting pylons to core at y=7 and y=10
    const bridgeConnections = [
      { bx: cx - 1, bz: cz - 2, ax: cx - 2, az: cz - 1 },
      { bx: cx + 1, bz: cz - 2, ax: cx + 2, az: cz - 1 },
      { bx: cx - 1, bz: cz + 2, ax: cx - 2, az: cz + 1 },
      { bx: cx + 1, bz: cz + 2, ax: cx + 2, az: cz + 1 }
    ];
    for (const b of bridgeConnections) {
      put(b.bx, 7, b.bz, getSlab("bottom"));
      put(b.ax, 7, b.az, getSlab("bottom"));
      put(b.bx, 10, b.bz, getSlab("top"));
      put(b.ax, 10, b.az, getSlab("top"));
    }

    // North Projector Array
    put(cx, 8, cz - 2, seaLantern);
    put(cx, 8, cz - 3, stonePrimary);
    put(cx, 9, cz - 3, getStair("north", "bottom"));

    // Apex Spire
    put(cx, 16, cz, amethystBlock);
    put(cx, 17, cz, amethystBlock);

  } else if (variant === 3) {
    // -----------------------------------------------------------
    // VARIANT 3: "The War-Shield Wardstone"
    // Fortified defensive monolith with heavy North projector dish
    // -----------------------------------------------------------
    for (let y = 7; y <= 13; y++) {
      for (let dx = -1; dx <= 1; dx++) {
        for (let dz = -1; dz <= 1; dz++) {
          if (dx === 0 && dz === 0) {
            put(cx, y, cz, (y === 8 || y === 12) ? seaLantern : cryingObsidian);
          } else if (y === 8 || y === 11) {
            put(cx + dx, y, cz + dz, cryingObsidian); // Defensive rune belt
          } else {
            put(cx + dx, y, cz + dz, stonePrimary);
          }
        }
      }
    }

    // Massive North Projector Array (Z=2..4, Y=7..10)
    put(cx, 8, cz - 2, seaLantern);
    put(cx, 8, cz - 3, amethystBlock);
    put(cx + 1, 8, cz - 2, getStair("east", "bottom"));
    put(cx - 1, 8, cz - 2, getStair("west", "bottom"));
    put(cx, 9, cz - 2, getStair("north", "bottom"));
    put(cx, 7, cz - 2, getStair("north", "top"));

    // Flanking Twin Horns (East & West)
    for (let y = 8; y <= 15; y++) {
      put(cx - 2, y, cz, y >= 14 ? amethystBlock : (y >= 11 ? getPillar("y") : stonePrimary));
      put(cx + 2, y, cz, y >= 14 ? amethystBlock : (y >= 11 ? getPillar("y") : stonePrimary));
    }

    // Fortified Crown
    put(cx, 14, cz, seaLantern);
    put(cx + 1, 14, cz, stoneWall);
    put(cx - 1, 14, cz, stoneWall);
    put(cx, 14, cz + 1, stoneWall);
    put(cx, 14, cz - 1, stoneWall);

    put(cx, 15, cz, amethystBlock);
    put(cx, 16, cz, amethystBlock);

  } else if (variant === 4) {
    // -----------------------------------------------------------
    // VARIANT 4: "The Resonant Tri-Spire"
    // Asymmetric trinity spires: Alpha(N), Beta(SE), Gamma(SW)
    // -----------------------------------------------------------
    // Fused Base Junction (y=7..8)
    for (let dx = -1; dx <= 1; dx++) {
      for (let dz = -1; dz <= 1; dz++) {
        put(cx + dx, 7, cz + dz, stonePrimary);
        put(cx + dx, 8, cz + dz, (dx === 0 && dz === 0) ? seaLantern : cryingObsidian);
      }
    }

    // Alpha Spire (North: (cx, cz-1)) -> tallest (y to 17)
    for (let y = 9; y <= 17; y++) {
      if (y <= 12) {
        put(cx, y, cz - 1, calcite);
        put(cx + 1, y, cz - 1, stonePrimary);
        put(cx - 1, y, cz - 1, stonePrimary);
      } else if (y <= 14) {
        put(cx, y, cz - 1, y === 14 ? seaLantern : getPillar("y"));
      } else {
        put(cx, y, cz - 1, amethystBlock);
      }
    }

    // Beta Spire (South-East: (cx+1, cz+1)) -> mid height (y to 14)
    for (let y = 9; y <= 14; y++) {
      if (y <= 11) {
        put(cx + 1, y, cz + 1, cryingObsidian);
        put(cx + 1, y, cz, stonePrimary);
      } else if (y === 12) {
        put(cx + 1, y, cz + 1, seaLantern);
      } else {
        put(cx + 1, y, cz + 1, amethystBlock);
      }
    }

    // Gamma Spire (South-West: (cx-1, cz+1)) -> low height (y to 12)
    for (let y = 9; y <= 12; y++) {
      if (y <= 10) {
        put(cx - 1, y, cz + 1, stonePrimary);
        put(cx - 1, y, cz, getPillar("y"));
      } else if (y === 11) {
        put(cx - 1, y, cz + 1, seaLantern);
      } else {
        put(cx - 1, y, cz + 1, amethystBlock);
      }
    }

  } else {
    // -----------------------------------------------------------
    // VARIANT 5: "The Overcharged Arch-Ward"
    // Flared crystal wings, outer resonant ring, towering apex
    // -----------------------------------------------------------
    // Core Shaft
    for (let y = 7; y <= 14; y++) {
      put(cx, y, cz, (y === 8 || y === 11 || y === 14) ? seaLantern : amethystBlock);
      put(cx + 1, y, cz, getPillar("y"));
      put(cx - 1, y, cz, getPillar("y"));
      put(cx, y, cz + 1, getPillar("y"));
      put(cx, y, cz - 1, getPillar("y"));
      put(cx + 1, y, cz + 1, cryingObsidian);
      put(cx - 1, y, cz + 1, cryingObsidian);
      put(cx + 1, y, cz - 1, cryingObsidian);
      put(cx - 1, y, cz - 1, cryingObsidian);
    }

    // Swept Wing Fins (y=8..12)
    const wings = [
      { x: cx, z: cz - 2, ox: cx, oz: cz - 3, dir: "north" },
      { x: cx, z: cz + 2, ox: cx, oz: cz + 3, dir: "south" },
      { x: cx + 2, z: cz, ox: cx + 3, oz: cz, dir: "east" },
      { x: cx - 2, z: cz, ox: cx - 3, oz: cz, dir: "west" }
    ];
    for (const w of wings) {
      put(w.x, 8, w.z, stonePrimary);
      put(w.x, 9, w.z, amethystBlock);
      put(w.x, 10, w.z, amethystBlock);
      put(w.x, 11, w.z, getStair(w.dir, "bottom"));
      put(w.ox, 9, w.oz, getStair(w.dir, "bottom"));
      put(w.ox, 10, w.oz, getSlab("top"));
    }

    // Resonant Ring Collar at y=10
    const ringBlocks = [
      [cx - 1, cz - 2], [cx + 1, cz - 2], [cx + 2, cz - 1], [cx + 2, cz + 1],
      [cx + 1, cz + 2], [cx - 1, cz + 2], [cx - 2, cz + 1], [cx - 2, cz - 1]
    ];
    for (const [rx, rz] of ringBlocks) {
      put(rx, 10, rz, cryingObsidian);
    }

    // Flared Apex Crystal Matrix (y=15..17)
    put(cx, 15, cz, seaLantern);
    put(cx + 1, 15, cz, amethystBlock);
    put(cx - 1, 15, cz, amethystBlock);
    put(cx, 15, cz + 1, amethystBlock);
    put(cx, 15, cz - 1, amethystBlock);

    put(cx, 16, cz, amethystBlock);
    put(cx + 1, 16, cz, stoneWall);
    put(cx - 1, 16, cz, stoneWall);
    put(cx, 16, cz + 1, stoneWall);
    put(cx, 16, cz - 1, stoneWall);

    put(cx, 17, cz, amethystBlock);
  }

  // -------------------------------------------------------------
  // 3. AMETHYST CLUSTER & CRYSTAL BUD GROWTH PASS
  // -------------------------------------------------------------
  // Grow clusters organically on exposed faces of crystal blocks
  for (let x = 0; x < W; x++) {
    for (let y = 4; y < H; y++) {
      for (let z = 0; z < D; z++) {
        const b = get(x, y, z);
        if (b && (b === amethystBlock || b === buddingAmethyst || b === cryingObsidian)) {
          // Check 6 adjacent directions
          const dirs = [
            { dir: "up", x: x, y: y + 1, z: z },
            { dir: "north", x: x, y: y, z: z - 1 },
            { dir: "south", x: x, y: y, z: z + 1 },
            { dir: "east", x: x + 1, y: y, z: z },
            { dir: "west", x: x - 1, y: y, z: z }
          ];

          for (const d of dirs) {
            if (d.x >= 0 && d.x < W && d.y >= 0 && d.y < H && d.z >= 0 && d.z < D) {
              if (get(d.x, d.y, d.z) === null) {
                // Growth chance
                const chance = (d.dir === "up" || (d.dir === "north" && d.z <= 3)) ? 0.65 : 0.28;
                if (rng() < chance) {
                  const size = (y >= 14 || d.dir === "up") ? 3 : (rng() < 0.5 ? 2 : 1);
                  tryAttachCluster(d.x, d.y, d.z, d.dir, size);
                }
              }
            }
          }
        }
      }
    }
  }

  // Guarantee high crystal crown cluster at apex
  for (let y = H - 1; y >= 14; y--) {
    if (isSolid(cx, y, cz) && y + 1 < H) {
      tryAttachCluster(cx, y + 1, cz, "up", 3);
      break;
    }
  }

  // -------------------------------------------------------------
  // 4. CONNECTIVITY VERIFICATION & EMIT
  // -------------------------------------------------------------
  // 6-connected flood fill from seat center (cx, SEAT_Y, cz)
  const visited = Array.from({ length: W }, () =>
    Array.from({ length: H }, () =>
      new Uint8Array(D)
    )
  );

  const queue = [[cx, SEAT_Y, cz]];
  visited[cx][SEAT_Y][cz] = 1;

  while (queue.length > 0) {
    const [qx, qy, qz] = queue.shift();
    const neighbors = [
      [qx + 1, qy, qz], [qx - 1, qy, qz],
      [qx, qy + 1, qz], [qx, qy - 1, qz],
      [qx, qy, qz + 1], [qx, qy, qz - 1]
    ];

    for (const [nx, ny, nz] of neighbors) {
      if (nx >= 0 && nx < W && ny >= 0 && ny < H && nz >= 0 && nz < D) {
        if (!visited[nx][ny][nz] && grid[nx][ny][nz] !== null) {
          visited[nx][ny][nz] = 1;
          queue.push([nx, ny, nz]);
        }
      }
    }
  }

  // Emit only solid connected blocks
  for (let x = 0; x < W; x++) {
    for (let y = 0; y < H; y++) {
      for (let z = 0; z < D; z++) {
        if (grid[x][y][z] !== null && visited[x][y][z]) {
          api.set(x, y, z, grid[x][y][z]);
        }
      }
    }
  }

  return {
    name: "Wardstone Crystal",
    seatY: SEAT_Y,
    anchors: {
      front: [cx, SEAT_Y, 0]
    }
  };
}
